/* ============================================================
   PATCH 1.0.12 — Уведомление об обновлении на главной + автообновление
   ============================================================ */
(function(){
'use strict';
if (window.__trkUpdateNotifierV3) return;
window.__trkUpdateNotifierV3 = true;

function _hasUpdatePerms() {
    var p = window.REESTR_PERMS || {};
    return !!(p['tab.updater'] || p['action.updater.apply']);
}

function _isDismissed() {
    try { return sessionStorage.getItem('trk_update_dismissed') === '1'; } catch(e) { return false; }
}

function _setDismissed(v) {
    try { sessionStorage.setItem('trk_update_dismissed', v ? '1' : '0'); } catch(e) {}
}

function _esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
}

// Безопасный fetch, чтобы HTML-ошибки не ломали JSON-парсер
function _safeJson(url, opts) {
    return fetch(url, opts || {credentials: 'same-origin'})
        .then(function(r) {
            var ct = r.headers.get('content-type') || '';
            if (ct.indexOf('application/json') !== -1) {
                return r.json();
            }
            return null;
        })
        .catch(function() { return null; });
}

function _checkUpdates() {
    if (!_hasUpdatePerms() || _isDismissed()) return;

    Promise.all([
        _safeJson('/api/plugins/updater/status'),
        _safeJson('/api/plugins/updater/settings')
    ]).then(function(results) {
        var d = results[0];
        var settings = results[1];

        if (d && d.success && d.pending && d.pending.length > 0) {
            var isAuto = settings && settings.success && settings.auto_update;
            if (isAuto) {
                if (typeof notify === 'function') notify('🚀 Найдено обновление, устанавливаем...', 'info');
                _runUpdate();
            } else {
                _showModal(d, false);
            }
        }
    }).catch(function(){});
}

function _showModal(d, isAuto) {
    var modal = document.getElementById('trkUpdateModal');
    if (!modal) return;

    var body = document.getElementById('trkUpdateBody');
    var html = '<p>Найдены новые патчи. Вот что изменится:</p>';
    html += '<ul style="margin: 10px 0 0 20px; padding: 0;">';
    (d.pending || []).forEach(function(p) {
        html += '<li style="margin-bottom: 6px;"><b>' + _esc(p.id) + '</b> — ' + _esc(p.description || 'Нет описания') + '</li>';
    });
    html += '</ul>';
    if (d.remote_version && d.remote_version !== d.version) {
        html += '<p style="margin-top: 12px; color: var(--trk-accent);">Версия изменится: <b>' + _esc(d.version) + '</b> → <b>' + _esc(d.remote_version) + '</b></p>';
    }
    body.innerHTML = html;

    var cbAuto = document.getElementById('trkUpdateAuto');
    if (cbAuto) {
        cbAuto.checked = isAuto;
        cbAuto.onchange = function() {
            var val = this.checked;
            var csrf = window.REESTR_CSRF || '';
            var hdrs = {'Content-Type': 'application/json'};
            if (csrf) hdrs['X-CSRF-Token'] = csrf;
            _safeJson('/api/plugins/updater/settings', {
                method: 'POST', credentials: 'same-origin', headers: hdrs,
                body: JSON.stringify({auto_update: val})
            });
        };
    }

    modal.classList.add('active');

    var btnDismiss = document.getElementById('trkUpdateDismiss');
    var btnApply = document.getElementById('trkUpdateApply');

    btnDismiss.onclick = function() {
        modal.classList.remove('active');
        _setDismissed(true);
    };

    btnApply.onclick = function() {
        modal.classList.remove('active');
        _runUpdate();
    };
}

function _runUpdate() {
    var loader = document.getElementById('globalLoader');
    if (loader) {
        loader.classList.add('active');
        var text = loader.querySelector('.gl-text');
        if (text) text.textContent = 'Обновление...';
    }

    var csrf = window.REESTR_CSRF || '';
    var hdrs = {'Content-Type': 'application/json'};
    if (csrf) hdrs['X-CSRF-Token'] = csrf;

    _safeJson('/api/plugins/updater/check', {
        method: 'POST', credentials: 'same-origin', headers: hdrs
    })
    .then(function(d){
        if (!d || !d.success || !d.dry_run || !d.dry_run.rc_ok) {
            throw new Error('Проверка не пройдена: ' + ((d && d.error) || 'неизвестная ошибка'));
        }
        if (loader) {
            var text = loader.querySelector('.gl-text');
            if (text) text.textContent = 'Применение патчей...';
        }
        return _safeJson('/api/plugins/updater/apply', {
            method: 'POST', credentials: 'same-origin', headers: hdrs
        });
    })
    .then(function(d){
        if (!d || !d.success) {
            throw new Error('Ошибка применения: ' + ((d && d.error) || 'неизвестная ошибка'));
        }
        if (loader) {
            var text = loader.querySelector('.gl-text');
            if (text) text.textContent = 'Перезагрузка сервера...';
        }
        return _safeJson('/api/settings/restart', {
            method: 'POST', credentials: 'same-origin', headers: hdrs
        });
    })
    .then(function(d){
        if (!d || !d.success) {
            throw new Error('Ошибка перезапуска: ' + ((d && d.error) || 'неизвестная ошибка'));
        }
        var attempts = 0;
        var iv = setInterval(function(){
            attempts++;
            fetch('/login', {method: 'HEAD', cache: 'no-store'})
                .then(function(){
                    clearInterval(iv);
                    location.reload();
                })
                .catch(function(){
                    if (attempts > 30) {
                        clearInterval(iv);
                        if (loader) loader.classList.remove('active');
                        alert('Сервер не поднялся. Пожалуйста, запустите START.bat вручную.');
                    }
                });
        }, 1000);
    })
    .catch(function(err){
        if (loader) loader.classList.remove('active');
        alert('❌ ' + err.message);
    });
}

setTimeout(_checkUpdates, 2000);
})();
